import "server-only";

// The airport table: every airport with an IATA code (10,238 of them), with its city, country,
// coordinates and IANA zone. Generated by scripts/build-airports.mjs (`npm run data:airports`)
// from airport-data-js (CC BY 4.0), with the zones re-derived from the coordinates.
//
// 886 kB of JSON: it stays on the server. Never import this module from a Client Component;
// reach it through a Server Component, a Server Action or GET /api/airports?q=.
import data from "@/data/airports.json";
import type { PlaceRef } from "@/lib/domain";

export type Airport = {
  iata: string;
  name: string;
  /** May be "" (1,380 small airports have no city in the source). */
  city: string;
  /** ISO 3166-1 alpha-2. */
  country: string;
  lat: number;
  lon: number;
  /** IANA zone, for example "America/New_York". */
  timeZone: string;
  /** 0..7: size in the upper bits, scheduled passenger service in the lowest. Bigger sorts first. */
  rank: number;
  /** IATA metropolitan-area code shared by a city's airports ("NYC", "LON"), or "". */
  metro: string;
};

type Row = [string, string, string, string, number, number, string, number, string];

const airports: Airport[] = (data.rows as Row[]).map(
  ([iata, name, city, country, lat, lon, timeZone, rank, metro]) => ({ iata, name, city, country, lat, lon, timeZone, rank, metro }),
);
const byIata = new Map(airports.map((a) => [a.iata, a]));

// Accent-insensitive, case-insensitive: "zurich" finds "Zürich", "sao paulo" finds "São Paulo".
const fold = (s: string) => s.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase();
const index = airports.map((a) => ({ a, name: fold(a.name), city: fold(a.city) }));

/** The line to print wherever the data is shown (CC BY 4.0 asks for attribution). */
export const airportsSource: string = data.source;

/** True when the airport has scheduled passenger service. */
export function hasScheduledService(airport: Pick<Airport, "rank">): boolean {
  return airport.rank % 2 === 1;
}

/** The airport with this IATA code ("mco" and " MCO " work), or undefined. */
export function airportByIata(code: string): Airport | undefined {
  return byIata.get(code.trim().toUpperCase());
}

/**
 * Airports matching what a person typed: a code ("MCO"), a city ("orlando", "new york" also
 * gives Newark through the metro code), or part of a name ("heathrow"). Best first: an exact
 * code, then the city, then names; bigger airports with scheduled service ahead of small ones.
 * Fewer than 2 characters gives nothing.
 */
export function searchAirports(query: string, limit = 8): Airport[] {
  const q = fold(query.trim());
  if (q.length < 2) return [];
  // "new york" should also return Newark: collect the metro codes of exact city matches.
  const metros = new Set<string>();
  for (const { a, city } of index) if (a.metro && city === q) metros.add(a.metro);

  const scored: { a: Airport; score: number }[] = [];
  for (const { a, name, city } of index) {
    let score = 0;
    if (a.iata.toLowerCase() === q) score = 1000;
    else if (a.metro && (a.metro.toLowerCase() === q || metros.has(a.metro))) score = 500;
    else if (city === q) score = 500;
    else if (city.startsWith(q)) score = 300;
    else if (name.startsWith(q)) score = 200;
    else if (q.length >= 3 && (name.includes(q) || city.includes(q))) score = 100;
    if (score) scored.push({ a, score: score + a.rank * 10 });
  }
  return scored
    .sort((x, y) => y.score - x.score || x.a.iata.localeCompare(y.a.iata))
    .slice(0, Math.max(0, limit))
    .map((s) => s.a);
}

const EARTH_RADIUS_KM = 6371.0088;
const toRadians = (degrees: number) => (degrees * Math.PI) / 180;

/** Great-circle distance in kilometres (haversine). */
export function distanceKm(latA: number, lonA: number, latB: number, lonB: number): number {
  const dLat = toRadians(latB - latA);
  const dLon = toRadians(lonB - lonA);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRadians(latA)) * Math.cos(toRadians(latB)) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.min(1, Math.sqrt(h)));
}

export type NearestAirportsOptions = {
  /**
   * "scheduled" (default): only airports with scheduled passenger service, the ones a person
   * can buy a ticket to. "all": every airport with a code, airstrips included.
   */
  service?: "scheduled" | "all";
  /** Ignore airports farther than this. Default: no limit. */
  withinKm?: number;
};

export type NearbyAirport = Airport & {
  /** Straight-line distance from the point, in kilometres, to one decimal. */
  distanceKm: number;
};

/**
 * The `n` airports closest to a point, nearest first. By default only airports with scheduled
 * passenger service count, so Orlando gives MCO and Sanford, not the executive airfield.
 * Distances are straight lines; the nearest airport is not always the quickest drive.
 */
export function nearestAirports(lat: number, lon: number, n = 3, options: NearestAirportsOptions = {}): NearbyAirport[] {
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || n <= 0) return [];
  const scheduledOnly = (options.service ?? "scheduled") === "scheduled";
  const within = options.withinKm ?? Number.POSITIVE_INFINITY;
  const found: NearbyAirport[] = [];
  for (const airport of airports) {
    if (scheduledOnly && !hasScheduledService(airport)) continue;
    const km = distanceKm(lat, lon, airport.lat, airport.lon);
    if (km > within) continue;
    found.push({ ...airport, distanceKm: Math.round(km * 10) / 10 });
  }
  return found.sort((a, b) => a.distanceKm - b.distanceKm || a.iata.localeCompare(b.iata)).slice(0, Math.floor(n));
}

/** An airport as a PlaceRef, ready to store as a destination, an origin or a pickup place. */
export function airportPlace(airport: Airport): PlaceRef {
  return {
    kind: "airport",
    name: airport.name,
    ...(airport.city ? { locality: airport.city } : {}),
    countryCode: airport.country,
    lat: airport.lat,
    lon: airport.lon,
    tz: airport.timeZone,
    iata: airport.iata,
  };
}
